; bits.asm -- chapter 21: a Graphic I page, and only R#1 changed
; generated by gen21.py
        INCLUDE "msx.inc"
        OUTPUT "bits.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; WHERE IT BREAKS. A page drawn by TEXT_PAGE for Graphic I; then every
; 8 frames a new value of R#1 (and of R#7), nothing else: the VDP reads the
; same tables as the mode bits tell it to.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 0
        ld hl, w0
        call puts
        ld b, 2
        ld c, 0
        ld hl, w1
        call puts
        ld b, 3
        ld c, 0
        ld hl, w2
        call puts
        ld b, 4
        ld c, 0
        ld hl, w3
        call puts
        ld b, 5
        ld c, 0
        ld hl, w4
        call puts
        ld b, 6
        ld c, 0
        ld hl, w5
        call puts
        ld b, 7
        ld c, 0
        ld hl, w6
        call puts
        ld b, 8
        ld c, 0
        ld hl, w7
        call puts
        ld b, 9
        ld c, 0
        ld hl, w8
        call puts
        ld b, 10
        ld c, 0
        ld hl, w9
        call puts
        ld b, 11
        ld c, 0
        ld hl, w10
        call puts
        ld b, 12
        ld c, 0
        ld hl, w11
        call puts
        ld b, 13
        ld c, 0
        ld hl, w12
        call puts
        ld b, 14
        ld c, 0
        ld hl, w13
        call puts
        ld b, 15
        ld c, 0
        ld hl, w14
        call puts
        ld b, 16
        ld c, 0
        ld hl, w15
        call puts
        ld b, 17
        ld c, 0
        ld hl, w16
        call puts
        ld b, 18
        ld c, 0
        ld hl, w17
        call puts
        ld b, 19
        ld c, 0
        ld hl, w18
        call puts
        ld b, 20
        ld c, 0
        ld hl, w19
        call puts
        ld b, 21
        ld c, 0
        ld hl, w20
        call puts
        ld b, 22
        ld c, 0
        ld hl, w21
        call puts
        ld b, 23
        ld c, 0
        ld hl, w22
        call puts
        VDP_REG 7, $1F          ; ink black, for text mode; backdrop white
        VDP_REG 1, $C0          ; the page on
        call frames             ; 8 frames of the state before
s0:     VDP_REG 1, $C0          ; Graphic I, as the page was drawn
        VDP_REG 7, $1F
t0:
        call frames             ; 8 frames of the state before
s1:     VDP_REG 1, $D0          ; M1: text mode
        VDP_REG 7, $1F
t1:
        call frames             ; 8 frames of the state before
s2:     VDP_REG 1, $C8          ; M2: multicolour
        VDP_REG 7, $1F
t2:
        call frames             ; 8 frames of the state before
s3:     VDP_REG 1, $D8          ; M1 and M2
        VDP_REG 7, $1F
t3:
        call frames             ; 8 frames of the state before
s4:     VDP_REG 1, $D0          ; M1, and R#7 as TEXT_PAGE left it
        VDP_REG 7, $0F
t4:
done:   jr done

; frames: wait for 8 frame flags, the interrupts off (chapter 19's status)
frames: ld b, 8
.wait:  in a, (VDP_CTRL)        ; bit 7, F: a frame has ended
        rla
        jr nc, .wait
        djnz .wait
        ret
w0:     db "A GRAPHIC I PAGE: ONLY R#1 MOVES", 0
w1:     db "02 THE VDP READS WHAT R#1 SAYS", 0
w2:     db "03 THE VDP READS WHAT R#1 SAYS", 0
w3:     db "04 THE VDP READS WHAT R#1 SAYS", 0
w4:     db "05 THE VDP READS WHAT R#1 SAYS", 0
w5:     db "06 THE VDP READS WHAT R#1 SAYS", 0
w6:     db "07 THE VDP READS WHAT R#1 SAYS", 0
w7:     db "08 THE VDP READS WHAT R#1 SAYS", 0
w8:     db "09 THE VDP READS WHAT R#1 SAYS", 0
w9:     db "10 THE VDP READS WHAT R#1 SAYS", 0
w10:     db "11 THE VDP READS WHAT R#1 SAYS", 0
w11:     db "12 THE VDP READS WHAT R#1 SAYS", 0
w12:     db "13 THE VDP READS WHAT R#1 SAYS", 0
w13:     db "14 THE VDP READS WHAT R#1 SAYS", 0
w14:     db "15 THE VDP READS WHAT R#1 SAYS", 0
w15:     db "16 THE VDP READS WHAT R#1 SAYS", 0
w16:     db "17 THE VDP READS WHAT R#1 SAYS", 0
w17:     db "18 THE VDP READS WHAT R#1 SAYS", 0
w18:     db "19 THE VDP READS WHAT R#1 SAYS", 0
w19:     db "20 THE VDP READS WHAT R#1 SAYS", 0
w20:     db "21 THE VDP READS WHAT R#1 SAYS", 0
w21:     db "22 THE VDP READS WHAT R#1 SAYS", 0
w22:     db "23 THE VDP READS WHAT R#1 SAYS", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
